    ])

    static func openCode(size: CGFloat) -> NSView {
        let view = IconStack(frame: NSRect(x: 0, y: 0, width: size, height: size))
        for (definition, color) in [(openCodeCenter, openCodeInner), (openCodeOuter, openCodeFill)] {
            let icon = IconView(definition: definition, size: size, color: color)
            icon.frame = view.bounds
            icon.autoresizingMask = [.width, .height]
            view.addSubview(icon)
        }
        return view
    }

    static func antigravity(size: CGFloat) -> NSView {
        let view = IconStack(frame: NSRect(x: 0, y: 0, width: size, height: size))
        view.wantsLayer = true
        view.layer?.contents = antigravityImage
        view.layer?.contentsGravity = .resizeAspect
        return view
    }

    private static let antigravityImage: NSImage? = Data(base64Encoded: antigravityPNG).flatMap(NSImage.init(data:))

    private static func hex(_ v: UInt32) -> NSColor {
        NSColor(srgbRed: CGFloat(v >> 16 & 0xFF) / 255, green: CGFloat(v >> 8 & 0xFF) / 255, blue: CGFloat(v & 0xFF) / 255, alpha: 1)
    }

    /// Decoration like `IconView`: clicks go to the control underneath.
    private final class IconStack: NSView {
        override var intrinsicContentSize: NSSize { frame.size }
        override func hitTest(_ point: NSPoint) -> NSView? { nil }
    }

    /// 128 x 128 PNG, `ANTIGRAVITY_ICON_DATA_URL`.
    private static let antigravityPNG = ""
}
